create table if not exists public.mission365_rate_windows (bucket text not null,subject text not null,window_start timestamptz not null,request_count integer not null default 0 check(request_count>=0),updated_at timestamptz not null default now(),primary key(bucket,subject,window_start));
alter table public.mission365_rate_windows enable row level security;revoke all on public.mission365_rate_windows from anon,authenticated;
create or replace function public.mission365_consume_rate_limit(p_bucket text,p_subject text,p_limit integer,p_window_seconds integer) returns boolean language plpgsql security definer set search_path='public','pg_temp' as $$ declare v_window timestamptz;v_count integer;begin if p_limit<1 or p_window_seconds<1 then return false;end if;v_window:=to_timestamp(floor(extract(epoch from now())/p_window_seconds)*p_window_seconds);insert into public.mission365_rate_windows(bucket,subject,window_start,request_count,updated_at) values(p_bucket,p_subject,v_window,1,now()) on conflict(bucket,subject,window_start) do update set request_count=public.mission365_rate_windows.request_count+1,updated_at=now() returning request_count into v_count;return v_count<=p_limit;end;$$;
revoke all on function public.mission365_consume_rate_limit(text,text,integer,integer) from public,anon,authenticated;grant execute on function public.mission365_consume_rate_limit(text,text,integer,integer) to service_role;create index if not exists mission365_rate_windows_cleanup_idx on public.mission365_rate_windows(updated_at);
